"""Verification point 1: .process-stick vs every .process-steps li, at
640/768/900/1024/1180/1279/1280, at scrollY 0.45/0.62/0.80 x docH. No pair
may have BOTH horizontal AND vertical overlap > 4px."""
import asyncio, json
from playwright.async_api import async_playwright
CHROME = "C:/Program Files/Google/Chrome/Application/chrome.exe"
BASE = "http://localhost:3301/tests/alunix-r8/runs/V3c/index.html"
WIDTHS = [640, 768, 900, 1024, 1180, 1279, 1280]
FRACS = [0.45, 0.62, 0.80]

def overlap_1d(a0, a1, b0, b1):
    return max(0, min(a1, b1) - max(a0, b0))

async def check(url_suffix, label):
    fails = []
    async with async_playwright() as p:
        b = await p.chromium.launch(executable_path=CHROME)
        for w in WIDTHS:
            page = await b.new_page(viewport={"width": w, "height": 900})
            await page.goto(BASE + url_suffix, wait_until="load", timeout=60000)
            await page.wait_for_timeout(800)
            doc_h = await page.evaluate("document.documentElement.scrollHeight")
            for frac in FRACS:
                await page.evaluate(f"window.scrollTo(0, {doc_h}*{frac})")
                await page.wait_for_timeout(300)
                data = await page.evaluate("""() => {
                  const stick = document.querySelector('.process-stick');
                  if (!stick) return null;
                  const sr = stick.getBoundingClientRect();
                  const lis = [...document.querySelectorAll('.process-steps li')];
                  return {stick: {l:sr.left,r:sr.right,t:sr.top,b:sr.bottom},
                    lis: lis.map(li => {const r = li.getBoundingClientRect();
                      return {l:r.left,r:r.right,t:r.top,b:r.bottom};})};
                }""")
                if data is None:
                    continue
                s = data["stick"]
                for i, li in enumerate(data["lis"]):
                    hx = overlap_1d(s["l"], s["r"], li["l"], li["r"])
                    vy = overlap_1d(s["t"], s["b"], li["t"], li["b"])
                    if hx > 4 and vy > 4:
                        fails.append(f"{label} w={w} frac={frac} li[{i}] hx={hx:.1f} vy={vy:.1f}")
            await page.close()
        await b.close()
    return fails

async def main():
    paper_fails = await check("", "papper")
    invert_fails = await check("?process=invert", "invert")
    print("PAPPER fails:", len(paper_fails))
    for f in paper_fails: print(" ", f)
    print("INVERT fails:", len(invert_fails))
    for f in invert_fails: print(" ", f)

asyncio.run(main())

