"""Render-identity check for R13: dump getComputedStyle of the relevant
selectors plus screenshots at 320/375/414/390/1440, at the process act
scroll position and at top. Run once before, once after."""
import asyncio, json, sys
from playwright.async_api import async_playwright
CHROME = "C:/Program Files/Google/Chrome/Application/chrome.exe"
BASE = "http://localhost:3301/tests/alunix-r8/runs/V3c/index.html"
WIDTHS = [(320, 844), (375, 812), (414, 896), (390, 844), (1440, 900)]

JS = """() => {
  const sel = ['.process-grid', '.process-stick', '.process-steps',
    '.process-steps li:nth-child(1)', '.process-p'];
  const out = {};
  for (const s of sel) {
    const el = document.querySelector(s);
    if (!el) { out[s] = null; continue; }
    const r = el.getBoundingClientRect();
    const cs = getComputedStyle(el);
    out[s] = {rect: {x:r.x,y:r.y,w:r.width,h:r.height},
      width: cs.width, justifySelf: cs.justifySelf};
  }
  return out;
}"""

async def run(tag):
    results = {}
    async with async_playwright() as p:
        b = await p.chromium.launch(executable_path=CHROME)
        for w, h in WIDTHS:
            page = await b.new_page(viewport={"width": w, "height": h})
            await page.goto(BASE, wait_until="load", timeout=60000)
            await page.wait_for_timeout(700)
            doc_h = await page.evaluate("document.documentElement.scrollHeight")
            await page.evaluate(f"window.scrollTo(0, {doc_h}*0.62)")
            await page.wait_for_timeout(300)
            data = await page.evaluate(JS)
            results[f"{w}x{h}"] = data
            await page.screenshot(path=f"p047_identity_{tag}_{w}.png")
            await page.close()
        await b.close()
    json.dump(results, open(f"p047_identity_{tag}.json", "w"), indent=1)
    return results

asyncio.run(run(sys.argv[1]))

