"""Point 2 (screenshots, read as images) + Point 3 (character measure, >=36
chars) + Point 5 (invert geometry matches paper) at 768/900/1024."""
import asyncio, json
from playwright.async_api import async_playwright
CHROME = "C:/Program Files/Google/Chrome/Application/chrome.exe"
BASE = "http://localhost:3301/tests/alunix-r8/runs/V3c/index.html"
OUT = "C:/Users/Anton L/anti-slop-design/tests/alunix-r8/runs/V3c/shots/r13"

MEASURE_JS = """() => {
  const p = document.querySelector('.process-steps li .process-p');
  if (!p) return null;
  const cs = getComputedStyle(p);
  const fontSize = parseFloat(cs.fontSize);
  // Find the widest wrapped line via Range per-line measurement.
  const range = document.createRange();
  const textNode = p.firstChild;
  if (!textNode || textNode.nodeType !== 3) return {text: p.textContent, fontSize};
  const text = textNode.textContent;
  let maxCharsInLine = 0, curLineStart = 0, lastTop = null;
  for (let i = 0; i <= text.length; i++) {
    range.setStart(textNode, i);
    range.setEnd(textNode, Math.min(i + 1, text.length));
    const rects = range.getClientRects();
    if (!rects.length) continue;
    const top = Math.round(rects[0].top);
    if (lastTop === null) lastTop = top;
    if (top !== lastTop) {
      maxCharsInLine = Math.max(maxCharsInLine, i - curLineStart);
      curLineStart = i;
      lastTop = top;
    }
  }
  maxCharsInLine = Math.max(maxCharsInLine, text.length - curLineStart);
  return {text, fontSize, maxCharsInLine, totalChars: text.length};
}"""

async def one(page, w, tag_suffix, mode_q):
    await page.set_viewport_size({"width": w, "height": 900})
    await page.goto(f"{BASE}{mode_q}", wait_until="load", timeout=60000)
    await page.wait_for_timeout(700)
    doc_h = await page.evaluate("document.documentElement.scrollHeight")
    await page.evaluate(f"window.scrollTo(0, {doc_h}*0.62)")
    await page.wait_for_timeout(400)
    await page.screenshot(path=f"{OUT}/process-{w}{tag_suffix}.png")
    m = await page.evaluate(MEASURE_JS)
    stick = await page.evaluate("""() => { const s=document.querySelector('.process-stick'); return s?s.getBoundingClientRect():null; }""")
    return m, stick

async def main():
    results = {}
    async with async_playwright() as p:
        b = await p.chromium.launch(executable_path=CHROME)
        page = await b.new_page()
        for w in (768, 900, 1024):
            m_p, s_p = await one(page, w, "", "")
            m_i, s_i = await one(page, w, "-invert", "?process=invert")
            results[w] = {"paper_measure": m_p, "invert_measure": m_i,
                          "stick_paper": s_p, "stick_invert": s_i}
            print(w, "paper maxCharsInLine=", m_p.get("maxCharsInLine") if m_p else None,
                  "invert maxCharsInLine=", m_i.get("maxCharsInLine") if m_i else None,
                  "stick_paper==stick_invert:", s_p == s_i)
        await b.close()
    json.dump(results, open("p047_measure.json", "w"), indent=1, default=str)

asyncio.run(main())

